import{_ as a,c as t,o as s,ag as i}from"./chunks/framework.DQvKz0xt.js";const c=JSON.parse('{"title":"网格 (Meshes) - Rive 编辑器","description":"网格允许你将点阵图像（如 PNG, JPG）或复杂的矢量形状转换为可变形的网格结构，从而实现自然且有机的动画效果。 你可以通过在图像或形状的检查器中点击“编辑网格 (Edit Mesh)”按钮来进入网格编辑模式。","frontmatter":{"title":"网格 (Meshes) - Rive 编辑器","description":"网格允许你将点阵图像（如 PNG, JPG）或复杂的矢量形状转换为可变形的网格结构，从而实现自然且有机的动画效果。 你可以通过在图像或形状的检查器中点击“编辑网格 (Edit Mesh)”按钮来进入网格编辑模式。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 形状操控, 网格"}]]},"headers":[],"relativePath":"editor/manipulating-shapes/meshes.md","filePath":"editor/manipulating-shapes/meshes.md","lastUpdated":1774838907000}'),r={name:"editor/manipulating-shapes/meshes.md"};function n(h,e,o,p,d,l){return s(),t("div",null,[...e[0]||(e[0]=[i('<p>操控形状</p><h1 id="网格-meshes" tabindex="-1">网格 (Meshes) <a class="header-anchor" href="#网格-meshes" aria-label="Permalink to &quot;网格 (Meshes)&quot;">​</a></h1><p>网格允许你将点阵图像（如 PNG, JPG）或复杂的矢量形状转换为可变形的网格结构，从而实现自然且有机的动画效果。</p><h2 id="​-创建网格" tabindex="-1"><a href="#creating-a-mesh">​</a> 创建网格 <a class="header-anchor" href="#​-创建网格" aria-label="Permalink to &quot;[​](#creating-a-mesh) 创建网格&quot;">​</a></h2><p>你可以通过在图像或形状的检查器中点击“编辑网格 (Edit Mesh)”按钮来进入网格编辑模式。 <img src="https://help.rive.app/images/edit-mesh.gif" alt="编辑网格 Pn"></p><h2 id="​-顶点权重" tabindex="-1"><a href="#vertex-weighting">​</a> 顶点权重 <a class="header-anchor" href="#​-顶点权重" aria-label="Permalink to &quot;[​](#vertex-weighting) 顶点权重&quot;">​</a></h2><p>在网格中，每个顶点都可以被赋予不同的权重，以决定它受骨骼影响的程度。这对于实现类似肌肉、布料或流体的平滑运动至关重要。</p><p><a href="/docs/editor/manipulating-shapes/bones">骨骼 (Bones)</a><a href="/docs/editor/manipulating-shapes/clipping">裁剪 (Clipping)</a></p>',8)])])}const _=a(r,[["render",n]]);export{c as __pageData,_ as default};
